parameters.jsonOutput:
={{ JSON.stringify({
  status: 'success',
  worker: 'responder',
  traceId: $('entrada_responder').item.json.traceId,
  entrada: $('entrada_responder').item.json,
  data: {
    respuesta: $json.output,
    codigo_ficha: ($json.output.match(/[A-Z]{3}-\d{3}/) || ['ninguna'])[0],
    derivado: $json.output.includes('Caso derivado a un especialista del área'),
    herramientas: ($json.intermediateSteps || []).map(s => s.action.tool + ' ' + JSON.stringify(s.action.toolInput)).join(' | ') || 'ninguna'
  }
}) }}

={{ JSON.stringify({
  status: 'error',
  worker: 'responder',
  traceId: $('entrada_responder').item.json.traceId,
  entrada: $('entrada_responder').item.json,
  data: {
    respuesta: 'No fue posible procesar su consulta en este momento. Caso derivado a un especialista del área.',
    codigo_ficha: 'ninguna',
    derivado: true,
    herramientas: 'ninguna',
    error: String($json.error?.message || $json.error || 'Error del agente')
  }
}) }}
